import { StyleSheet } from "@formepdf/react";

import type { PdfcnTheme } from "@/registry/types/pdf-themes";

/**
 * Creates all table styles derived from the active theme.
 * @param t - The resolved PdfcnTheme instance.
 */
export const createTableStyles = (t: PdfcnTheme) => {
  const { spacing, borderRadius, fontWeights, typography } = t.primitives;
  const borderColor = t.colors.border;

  const hairline = 0.5;
  const rule = 1;
  const thick = 1.5;

  const cellPadV = spacing[2] - 2;
  const cellPadH = spacing[2] + 2;
  // eslint-disable-next-line prefer-destructuring
  const cellPadVCompact = spacing[0.5];
  // eslint-disable-next-line prefer-destructuring
  const cellPadHCompact = spacing[2];

  const rowDivider = {
    borderBottomColor: borderColor,
    borderBottomStyle: "solid" as const,
    borderBottomWidth: hairline,
  };

  return StyleSheet.create({
    cell: {
      flex: 1,
      justifyContent: "center",
      paddingHorizontal: cellPadH,
      paddingVertical: cellPadV,
    },

    cellBordered: {
      paddingHorizontal: cellPadH,
      paddingVertical: cellPadV,
    },

    cellBorderedBorder: {
      borderRightColor: borderColor,
      borderRightStyle: "solid",
      borderRightWidth: hairline,
    },

    cellCompact: {
      paddingHorizontal: cellPadHCompact,
      paddingVertical: cellPadVCompact,
    },

    cellFixed: {
      flexGrow: 0,
      flexShrink: 0,
      justifyContent: "center",
      paddingHorizontal: cellPadH,
      paddingVertical: cellPadV,
    },

    cellGridBorder: {
      borderRightColor: borderColor,
      borderRightStyle: "solid",
      borderRightWidth: hairline,
    },

    cellMinimal: {
      paddingHorizontal: spacing[2] - 2,
      paddingVertical: spacing[1] + 1,
    },

    cellPrimaryHeader: {
      paddingHorizontal: cellPadH,
      paddingVertical: cellPadV,
    },

    cellStriped: {
      paddingHorizontal: cellPadH,
      paddingVertical: cellPadV,
    },

    cellText: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      lineHeight: 1.2,
    },
    cellTextCompact: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.xs,
      lineHeight: 1.2,
    },
    cellTextFooter: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.semibold,
      lineHeight: 1.2,
    },
    cellTextHeaderBordered: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.bold,
      lineHeight: 1.2,
    },
    cellTextHeaderCompact: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.xs,
      fontWeight: fontWeights.semibold,
      letterSpacing: 0.6,
      lineHeight: 1.2,
      textTransform: "uppercase",
    },
    cellTextHeaderGrid: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.semibold,
      lineHeight: 1.2,
    },
    cellTextHeaderLine: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.semibold,
      lineHeight: 1.2,
    },

    cellTextHeaderMinimal: {
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.medium,
      lineHeight: 1.2,
    },
    cellTextHeaderPrimaryHeader: {
      color: t.colors.primaryForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.xs,
      fontWeight: fontWeights.semibold,
      letterSpacing: 0.6,
      lineHeight: 1.2,
      textTransform: "uppercase",
    },
    cellTextHeaderStriped: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.semibold,
      lineHeight: 1.2,
    },
    row: {
      display: "flex",
      flexDirection: "row",
    },
    rowBordered: rowDivider,
    rowCompact: rowDivider,
    rowFooter: {
      borderTopColor: borderColor,
      borderTopStyle: "solid",
      borderTopWidth: rule,
    },

    rowFooterStriped: {
      backgroundColor: t.colors.muted,
      borderTopColor: borderColor,
      borderTopStyle: "solid",
      borderTopWidth: rule,
    },
    rowGrid: rowDivider,

    rowHeaderBordered: {
      backgroundColor: t.colors.muted,
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: hairline,
    },

    rowHeaderCompact: {
      backgroundColor: t.colors.muted,
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: rule,
    },
    rowHeaderGrid: {
      backgroundColor: t.colors.muted,
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: rule,
    },

    rowHeaderLine: {
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: rule,
    },
    rowHeaderMinimal: {
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: rule,
    },
    rowHeaderPrimaryHeader: {
      backgroundColor: t.colors.primary,
    },
    rowHeaderStriped: {
      backgroundColor: t.colors.muted,
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: rule,
    },
    rowLine: rowDivider,

    rowMinimal: rowDivider,
    rowPrimaryHeader: rowDivider,

    rowStripe: {
      backgroundColor: t.colors.muted,
    },

    rowStriped: {},
    table: {
      display: "flex",
      flexDirection: "column",
      marginBottom: t.spacing.componentGap,
      width: "100%",
    },
    tableBordered: {
      borderBottomLeftRadius: borderRadius.sm,
      borderBottomRightRadius: borderRadius.sm,
      borderColor,
      borderStyle: "solid",
      borderTopLeftRadius: borderRadius.sm,
      borderTopRightRadius: borderRadius.sm,
      borderWidth: rule,
      overflow: "hidden" as const,
    },
    tableCompact: {
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: hairline,
    },
    tableGrid: {
      borderBottomLeftRadius: borderRadius.md,
      borderBottomRightRadius: borderRadius.md,
      borderColor,
      borderStyle: "solid",
      borderTopLeftRadius: borderRadius.md,
      borderTopRightRadius: borderRadius.md,
      borderWidth: thick,
      overflow: "hidden" as const,
    },
    tableLine: {
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: hairline,
    },
    tableMinimal: {
      paddingVertical: spacing[2],
    },

    tablePrimaryHeader: {
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: hairline,
    },

    tableStriped: {
      borderBottomColor: borderColor,
      borderBottomStyle: "solid",
      borderBottomWidth: hairline,
      borderTopColor: borderColor,
      borderTopStyle: "solid",
      borderTopWidth: hairline,
    },
  });
};

import { Children, cloneElement, isValidElement } from "react";
import type { ReactElement, ReactNode } from "react";

import {
  usePdfcnTheme,
  useSafeMemo,
} from "@/registry/bases/forme/components/theme-provider";
import {
  Text as PDFText,
  View,
} from "@/registry/bases/forme/lib/pdf-primitives";
import type { Style } from "@/registry/bases/forme/lib/pdf-primitives";

import { createTableStyles } from "./table.styles";
import type {
  TableCellProps,
  TableProps,
  TableRowProps,
  TableSectionProps,
  TableVariant,
} from "./table.types";

export const TableHeader = ({ children, style }: TableSectionProps) => (
  <View style={style}>{children}</View>
);

export const TableBody = ({ children, style }: TableSectionProps) => (
  <View style={style}>{children}</View>
);

export const TableFooter = ({ children, style }: TableSectionProps) => (
  <View style={style}>{children}</View>
);

export const TableCell = ({
  header,
  footer,
  align,
  width,
  children,
  style,
  variant = "line",
  _last,
}: TableCellProps) => {
  const theme = usePdfcnTheme();
  const styles = useSafeMemo(() => createTableStyles(theme), [theme]);
  const cellStyles: Style[] =
    width === undefined
      ? [styles.cell]
      : [styles.cellFixed, { width } as Style];

  const cellVariantStyle = (
    {
      bordered: styles.cellBordered,
      compact: styles.cellCompact,
      minimal: styles.cellMinimal,
      "primary-header": styles.cellPrimaryHeader,
      striped: styles.cellStriped,
    } as Partial<Record<TableVariant, Style>>
  )[variant];
  if (cellVariantStyle) {
    cellStyles.push(cellVariantStyle);
  }

  if (variant === "grid" && !_last) {
    cellStyles.push(styles.cellGridBorder);
  } else if (variant === "bordered" && !_last) {
    cellStyles.push(styles.cellBorderedBorder);
  }

  if (align) {
    cellStyles.push({ textAlign: align } as Style);
  }

  const styleArray = style ? [...cellStyles, style] : cellStyles;

  let textStyle: Style = styles.cellText;
  if (header) {
    textStyle = {
      bordered: styles.cellTextHeaderBordered,
      compact: styles.cellTextHeaderCompact,
      grid: styles.cellTextHeaderGrid,
      line: styles.cellTextHeaderLine,
      minimal: styles.cellTextHeaderMinimal,
      "primary-header": styles.cellTextHeaderPrimaryHeader,
      striped: styles.cellTextHeaderStriped,
    }[variant];
  } else if (footer) {
    textStyle = styles.cellTextFooter;
  } else if (variant === "compact") {
    textStyle = styles.cellTextCompact;
  }

  const content =
    typeof children === "string" ? (
      <PDFText
        style={
          [
            textStyle,
            align ? { textAlign: align } : {},
            { margin: 0, padding: 0 },
          ] as never
        }
      >
        {children}
      </PDFText>
    ) : (
      children
    );

  return <View style={styleArray as never}>{content}</View>;
};

export const TableRow = ({
  header,
  footer,
  stripe,
  children,
  style,
  variant = "line",
}: TableRowProps) => {
  const theme = usePdfcnTheme();
  const styles = useSafeMemo(() => createTableStyles(theme), [theme]);
  const rowStyles: Style[] = [
    styles.row,
    {
      bordered: styles.rowBordered,
      compact: styles.rowCompact,
      grid: styles.rowGrid,
      line: styles.rowLine,
      minimal: styles.rowMinimal,
      "primary-header": styles.rowPrimaryHeader,
      striped: styles.rowStriped,
    }[variant],
  ];

  if (header) {
    rowStyles.push(
      {
        bordered: styles.rowHeaderBordered,
        compact: styles.rowHeaderCompact,
        grid: styles.rowHeaderGrid,
        line: styles.rowHeaderLine,
        minimal: styles.rowHeaderMinimal,
        "primary-header": styles.rowHeaderPrimaryHeader,
        striped: styles.rowHeaderStriped,
      }[variant]
    );
  }

  if (footer) {
    if (variant === "striped") {
      rowStyles.push(styles.rowFooterStriped);
    } else {
      rowStyles.push(styles.rowFooter);
    }
  }

  if (stripe && !header && !footer) {
    rowStyles.push(styles.rowStripe);
  }

  const styleArray = style ? [...rowStyles, style] : rowStyles;
  const childArray = Children.toArray(children);
  const processedChildren = childArray.map((child, i) => {
    if (isValidElement(child) && child.type === TableCell) {
      return cloneElement(child as ReactElement<TableCellProps>, {
        _last: i === childArray.length - 1,
        footer,
        header,
        variant,
      });
    }
    return child;
  });

  return (
    <View wrap={false} style={styleArray as never}>
      {processedChildren}
    </View>
  );
};

const processTableChildren = (
  children: ReactNode,
  variant: TableVariant,
  zebraStripe: boolean
): ReactNode => {
  let bodyRowIndex = 0;

  return Children.map(children, (child) => {
    if (!isValidElement(child)) {
      return child;
    }

    if (
      child.type === TableHeader ||
      child.type === TableBody ||
      child.type === TableFooter
    ) {
      const isBody = child.type === TableBody;
      const sectionChild = child as ReactElement<TableSectionProps>;
      const sectionChildren = Children.map(
        sectionChild.props.children,
        (rowChild) => {
          if (isValidElement(rowChild) && rowChild.type === TableRow) {
            const rowProps: Partial<TableRowProps> = { variant };

            if (isBody && zebraStripe) {
              const isStripe = bodyRowIndex % 2 === 1;
              bodyRowIndex += 1;
              if (isStripe) {
                rowProps.stripe = true;
              }
            }

            return cloneElement(
              rowChild as ReactElement<TableRowProps>,
              rowProps
            );
          }
          return rowChild;
        }
      );

      return cloneElement(child, {}, sectionChildren);
    }

    if (child.type === TableRow) {
      return cloneElement(child as ReactElement<TableRowProps>, { variant });
    }

    return child;
  });
};

export const Table = ({
  children,
  style,
  variant = "line",
  zebraStripe = false,
  noWrap = false,
}: TableProps) => {
  const theme = usePdfcnTheme();
  const styles = useSafeMemo(() => createTableStyles(theme), [theme]);
  const tableStyles: Style[] = [styles.table];
  const effectiveZebra = variant === "striped" ? true : zebraStripe;

  tableStyles.push(
    {
      bordered: styles.tableBordered,
      compact: styles.tableCompact,
      grid: styles.tableGrid,
      line: styles.tableLine,
      minimal: styles.tableMinimal,
      "primary-header": styles.tablePrimaryHeader,
      striped: styles.tableStriped,
    }[variant]
  );

  const styleArray = style ? [...tableStyles, style] : tableStyles;
  const processedChildren = processTableChildren(
    children,
    variant,
    effectiveZebra
  );

  const inner = <View style={styleArray as never}>{processedChildren}</View>;
  return noWrap ? <View wrap={false}>{inner}</View> : inner;
};

import type { PDFComponentProps } from "@/registry/types/pdf-components";

/** Table visual style variant. */
export type TableVariant =
  | "line"
  | "grid"
  | "minimal"
  | "striped"
  | "compact"
  | "bordered"
  | "primary-header";

/**
 * Table container with visual style variants and optional zebra striping.
 * Props - `variant` | `zebraStripe` | `noWrap` | `children` | `style`
 * @see {@link TableProps}
 */
export interface TableProps extends PDFComponentProps {
  /**
   * @default 'line'
   */
  variant?: TableVariant;
  /**
   * @default false
   */
  zebraStripe?: boolean;
  /**
   * @default false
   */
  noWrap?: boolean;
}

export type TableSectionProps = PDFComponentProps;

/**
 * Table row with optional header, footer, and stripe states.
 * Props - `header` | `footer` | `stripe` | `variant` | `children` | `style`
 * @see {@link TableRowProps}
 */
export interface TableRowProps extends PDFComponentProps {
  header?: boolean;
  footer?: boolean;
  stripe?: boolean;
  variant?: TableVariant;
}

/**
 * Table cell with alignment, width, and header or footer text styling.
 * Props - `header` | `footer` | `align` | `width` | `variant` | `_last` | `children` | `style`
 * @see {@link TableCellProps}
 */
export interface TableCellProps extends PDFComponentProps {
  header?: boolean;
  footer?: boolean;
  align?: "left" | "center" | "right";
  width?: string | number;
  variant?: TableVariant;
  _last?: boolean;
}
